SELECT AdmLName1, District, County, School
FROM schools
WHERE CharterNum = '40';

SELECT * FROM account WHERE account_id IN (
    SELECT account_id FROM loan
    WHERE status = 'A' AND strftime('%Y', date) = '1997'
    AND amount = (
        SELECT MIN(amount)
        FROM loan
        WHERE status = 'A' AND strftime('%Y', date) = '1997'
    )
)
AND frequency = 'POPLATEK TYDNE';

SELECT A2, A3
FROM district
WHERE A13 = (SELECT MAX(A13) FROM district);

SELECT
    (SELECT COUNT(*) FROM trans WHERE account_id = 3 AND k_symbol = 'VYPIS') AS statement_requests_by_account_3,
    (SELECT k_symbol FROM trans WHERE trans_id = 3539 AND type = 'VYDAJ') AS aim_of_debiting_3539;

SELECT DISTINCT a.*
FROM atom a
WHERE a.atom_id IN (
    SELECT atom_id2 FROM connected WHERE atom_id IN (
        SELECT atom_id FROM atom WHERE molecule_id = 'TR181'
    )
    UNION
    SELECT atom_id FROM connected WHERE atom_id2 IN (
        SELECT atom_id FROM atom WHERE molecule_id = 'TR181'
    )
);

SELECT ROUND(100.0 * SUM(bond_type = '=') / COUNT(bond_id), 5) AS percentage
FROM bond
WHERE molecule_id = 'TR008';

SELECT ROUND(SUM(CASE WHEN LOWER(element) = 'h' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 4) AS percent
FROM atom
WHERE molecule_id = 'TR206';

SELECT COUNT(*)
FROM connected
WHERE atom_id = '19' OR atom_id2 = '19';

SELECT 100.0 * COUNT(DISTINCT bond.molecule_id) / (SELECT COUNT(*) FROM molecule) AS percent
FROM bond
WHERE bond_type = '#';

SELECT CAST(SUM(CASE WHEN bond_type = ' = ' THEN 1 ELSE 0 END) AS REAL) / COUNT(*) * 100 AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT COUNT(*) 
FROM molecule 
WHERE label = '+';

SELECT atom_id, element
FROM atom
WHERE molecule_id = 'TR186';

SELECT name
FROM cards
WHERE artist = 'Aaron Boyd';

SELECT name, colors
FROM cards
WHERE setCode = 'OGW';

SELECT SUM(convertedManaCost) AS total_mana_cost
FROM cards
WHERE artist = 'Rob Alexander';

SELECT (COUNT(CASE WHEN isOnlineOnly = 1 THEN 1 END) * 100.0) / COUNT(*) AS percentage
FROM cards
WHERE frameEffects = 'legendary';

SELECT COUNT(*)
FROM cards
WHERE isOversized = 1 AND isReprint = 1 AND isPromo = 1;

SELECT DISTINCT language
FROM set_translations
WHERE setCode = (SELECT code FROM sets WHERE name = 'Battlebond');

SELECT DISTINCT artist
FROM cards
WHERE borderColor = 'black' AND availability = 'arena';

SELECT DisplayName
FROM users
WHERE strftime('%Y', CreationDate) = '2011';

SELECT DisplayName
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT 
    (SELECT GROUP_CONCAT(DISTINCT PostHistoryTypeId) FROM postHistory WHERE PostId = 3720) AS PostHistoryTypeIds,
    (SELECT COUNT(DISTINCT UserId) FROM comments WHERE PostId = 3720) AS UniqueCommenters;

SELECT posts.*, (SELECT ViewCount FROM posts WHERE Id = 61217) AS Popularity
FROM posts
WHERE posts.Id IN (
    SELECT RelatedPostId FROM postLinks WHERE PostId = 61217
);

SELECT COUNT(DISTINCT UserId)
FROM badges
WHERE Name = 'Announcer';

SELECT (COUNT(DISTINCT UserId) * 100.0 / (SELECT COUNT(*) FROM users)) AS percentage
FROM badges
WHERE Name = 'Teacher';

SELECT COUNT(*) 
FROM users 
WHERE Location LIKE '%New York%';

SELECT CAST(COUNT(*) AS REAL) / NULLIF((SELECT COUNT(*) FROM votes WHERE strftime('%Y', CreationDate) = '2011'), 0) AS ratio
FROM votes
WHERE strftime('%Y', CreationDate) = '2010';

SELECT CAST(SUM(CASE WHEN Tags LIKE '%<r>%' THEN 1 ELSE 0 END) AS REAL) * 100 / NULLIF(COUNT(*), 0) AS percentage
FROM posts
WHERE OwnerDisplayName = 'Community';

SELECT COUNT(DISTINCT UserId)
FROM badges
WHERE Name = 'Commentator' AND strftime('%Y', Date) = '2014';

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT COUNT(*)
FROM posts
WHERE ViewCount > (SELECT AVG(ViewCount) FROM posts);

SELECT AVG(CASE WHEN Score > 50 THEN 100.0 ELSE 0 END) AS percentage
FROM posts
WHERE OwnerUserId = (SELECT Id FROM users ORDER BY Reputation DESC LIMIT 1);

SELECT CAST(SUM(CASE WHEN c.colour = 'No Colour' THEN 1 ELSE 0 END) AS REAL) / COUNT(*) AS proportion
FROM superhero s
LEFT JOIN colour c ON s.skin_colour_id = c.id;

SELECT COUNT(*) 
FROM hero_power 
WHERE hero_id = (SELECT id FROM superhero WHERE superhero_name = 'Amazo');

SELECT (SUM(CASE WHEN c.colour = 'Blue' THEN 1 ELSE 0 END) * 100.0 / COUNT(*)) AS percentage_blue_eyes
FROM superhero s
LEFT JOIN colour c ON s.eye_colour_id = c.id;

SELECT (SUM(CASE WHEN gender_id = 2 THEN 1 ELSE 0 END) * 100.0) / COUNT(*) AS percentage
FROM superhero
WHERE alignment_id = 2;

SELECT SUM(CASE WHEN eye_colour_id = 7 THEN 1 ELSE 0 END) - SUM(CASE WHEN eye_colour_id = 1 THEN 1 ELSE 0 END) AS difference
FROM superhero
WHERE weight_kg = 0 OR weight_kg IS NULL;

SELECT COUNT(*)
FROM superhero
WHERE full_name LIKE 'John%';

SELECT DISTINCT nationality
FROM drivers
WHERE dob = (SELECT MIN(dob) FROM drivers WHERE dob IS NOT NULL);

SELECT DISTINCT year
FROM races
WHERE circuitId = (SELECT circuitId FROM circuits WHERE name = 'Silverstone Circuit');

SELECT CAST(SUM(CASE WHEN time IS NOT NULL THEN 1 ELSE 0 END) AS REAL) / COUNT(*) AS rate
FROM results
WHERE raceId = (
    SELECT raceId FROM races WHERE year = 2008 AND name = 'Australian Grand Prix'
);

SELECT raceId
FROM races
WHERE year = 2009;

SELECT duration
FROM pitStops
WHERE milliseconds = (SELECT MAX(milliseconds) FROM pitStops);

SELECT DISTINCT player_api_id
FROM Player_Attributes
WHERE overall_rating = (
    SELECT MAX(overall_rating)
    FROM Player_Attributes
);

SELECT DISTINCT team_fifa_api_id
FROM Team_Attributes
WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;

SELECT CAST(SUM(CASE WHEN preferred_foot = 'left' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS REAL) AS percentage
FROM Player
WHERE strftime('%Y', birthday) BETWEEN '1987' AND '1992';

SELECT player_name
FROM Player
WHERE height = (SELECT MAX(height) FROM Player);

SELECT COUNT(DISTINCT player_api_id) 
FROM Player_Attributes 
WHERE preferred_foot = 'left' AND attacking_work_rate = 'low';

SELECT (COUNT(CASE WHEN Admission = '+' THEN 1 END) * 100.0 / COUNT(*)) AS percentage
FROM Patient
WHERE Birthday BETWEEN '1930-01-01' AND '1940-12-31';

SELECT CASE WHEN `T-CHO` < 250 THEN 'Normal' ELSE 'Abnormal' END AS Cholesterol_Status
FROM Laboratory
WHERE ID = 2927464 AND Date = '1995-09-04';

SELECT (SUM(CASE WHEN UA <= 6.5 THEN 1 ELSE 0 END) * 100.0) / COUNT(*)
FROM Laboratory
WHERE CAST("U-PRO" AS REAL) > 0 AND CAST("U-PRO" AS REAL) < 30;

SELECT (SUM(CASE WHEN Diagnosis = 'BEHCET' THEN 1 ELSE 0 END) * 100.0) / COUNT(*)
FROM Patient
WHERE SEX = 'M' AND strftime('%Y', "First Date") = '1981';

SELECT (CAST(SUM(CASE WHEN SEX = 'F' THEN 1 ELSE 0 END) AS REAL) * 100) / COUNT(*) 
FROM Patient
WHERE STRFTIME('%Y', Birthday) = '1980' AND Diagnosis = 'RA';

SELECT Date
FROM Laboratory
WHERE ID = 48473 AND GOT >= 60;

SELECT COUNT(DISTINCT Patient.ID) 
FROM Patient 
WHERE EXISTS (
    SELECT 1 FROM Laboratory WHERE Laboratory.ID = Patient.ID AND Laboratory.RA IN ('-', '+-')
)
AND EXISTS (
    SELECT 1 FROM Examination WHERE Examination.ID = Patient.ID AND Examination.KCT = '+'
);

SELECT COUNT(DISTINCT Patient.ID) 
FROM Patient 
WHERE EXISTS (
    SELECT 1 FROM Examination 
    WHERE Examination.ID = Patient.ID AND Examination.Diagnosis = 'SLE'
) 
AND EXISTS (
    SELECT 1 FROM Laboratory 
    WHERE Laboratory.ID = Patient.ID AND Laboratory.SSB IN ('negative', '0')
);

SELECT COUNT(DISTINCT Patient.ID)
FROM Patient
WHERE EXISTS (
    SELECT 1 FROM Laboratory
    WHERE Laboratory.ID = Patient.ID AND TG < 200
)
AND EXISTS (
    SELECT 1 FROM Examination
    WHERE Examination.ID = Patient.ID AND Symptoms IS NOT NULL
);

SELECT COUNT(DISTINCT Patient.ID)
FROM Patient
WHERE Patient.ID IN (
    SELECT ID FROM Laboratory WHERE CPK < 250
)
AND Patient.ID IN (
    SELECT ID FROM Examination
    WHERE KCT = '+' OR RVVT = '+' OR LAC = '+'
);

SELECT expense_description
FROM expense
WHERE cost = (SELECT MAX(cost) FROM expense);

SELECT spent FROM budget
JOIN event ON budget.link_to_event = event.event_id
WHERE event.event_name = 'September Meeting' AND budget.category = 'Food';

SELECT COUNT(*) 
FROM member 
WHERE position = 'President';

SELECT COUNT(*) FROM member
JOIN major ON member.link_to_major = major.major_id
WHERE major.major_name = 'Physics Teaching';

SELECT AVG(spent)
FROM budget
WHERE category = 'Food' AND event_status = 'Closed';

SELECT (SUM(CASE WHEN type = 'Community Service' THEN 1 ELSE 0 END) * 100.0 / COUNT(event_id)) AS percentage_share
FROM event
WHERE event_date BETWEEN '2019-01-01' AND '2019-12-31';

SELECT DISTINCT county
FROM zip_code
WHERE type = 'PO Box';

SELECT (COUNT(DISTINCT b.link_to_event) * 100.0) / COUNT(DISTINCT e.event_id) AS percentage
FROM event e
LEFT JOIN budget b ON e.event_id = b.link_to_event AND b.remaining < 0;

SELECT
    (SELECT COUNT(*) FROM customers WHERE Segment = 'SME' AND Currency = 'CZK') -
    (SELECT COUNT(*) FROM customers WHERE Segment = 'SME' AND Currency = 'EUR') AS amount_more_smes_czk_vs_eur;

SELECT (COUNT(CASE WHEN Consumption > 528.3 THEN 1 END) * 100.0) / COUNT(*) AS percentage
FROM yearmonth
WHERE Date = '201202';

SELECT ProductID
FROM transactions_1k
WHERE Date = '2012-08-23' AND Time = '21:20:00';

SELECT 100.0 * SUM(CASE WHEN LOWER(Segment) = 'premium' THEN 1 ELSE 0 END) / COUNT(*) AS Percentage
FROM gasstations
WHERE Country = 'SVK';
